import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

rms_norm_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void rmsnorm_sum_of_squares_kernel(const float* __restrict__ x,
                                              float* __restrict__ sums,
                                              int N, int F, int H, int W) {
    int idx = blockDim.x * blockIdx.x + threadIdx.x;
    int total = N * H * W;
    if (idx < total) {
        int j = idx % W;
        int i = (idx / W) % H;
        int n = idx / (H * W);
        float sum_squares = 0.0f;
        int base = (n * F * H + i) * W + j;
        for (int f = 0; f < F; f++) {
            float val = x[base + f * H * W];
            sum_squares += val * val;
        }
        sums[idx] = sum_squares;
    }
}

__global__ void rmsnorm_apply_kernel(const float* __restrict__ x,
                                     const float* __restrict__ sums,
                                     float* __restrict__ out,
                                     int N, int F, int H, int W, float eps) {
    int idx = blockDim.x * blockIdx.x + threadIdx.x;
    int total = N * F * H * W;
    if (idx < total) {
        int w = idx % W;
        int h = (idx / W) % H;
        int f = (idx / (H * W)) % F;
        int n = idx / (F * H * W);
        int sum_idx = n * H * W + h * W + w;
        float mean_sq = sums[sum_idx] / (float)F;
        float denom = sqrtf(mean_sq + eps);
        out[idx] = x[idx] / denom;
    }
}

torch::Tensor rms_norm_forward_cuda(torch::Tensor x, int64_t num_features, double eps) {
    // x shape: [N, F, H, W]
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat, "x must be float type");
    int N = x.size(0);
    int F = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    auto sums = torch::zeros({N, H, W}, x.options());
    auto out = torch::empty_like(x);

    int blocks1 = (N * H * W + 255) / 256;
    dim3 threads(256);

    rmsnorm_sum_of_squares_kernel<<<blocks1, threads>>>(
        x.data_ptr<float>(), sums.data_ptr<float>(), N, F, H, W);

    int blocks2 = (N * F * H * W + 255) / 256;
    rmsnorm_apply_kernel<<<blocks2, threads>>>(
        x.data_ptr<float>(), sums.data_ptr<float>(), out.data_ptr<float>(),
        N, F, H, W, static_cast<float>(eps));

    return out;
}
'''

rms_norm_header = """
torch::Tensor rms_norm_forward_cuda(torch::Tensor x, int64_t num_features, double eps);
"""

rms_norm_module = load_inline(
    name="rms_norm_module",
    cpp_sources=rms_norm_header,
    cuda_sources=rms_norm_source,
    extra_include_paths=[],
    extra_cflags=[],
    extra_cuda_cflags=[],
    extra_ldflags=[],
    verbose=False,
    functions=["rms_norm_forward_cuda"]
)

class ModelNew(nn.Module):
    def __init__(self, num_features: int, eps: float = 1e-5):
        super().__init__()
        self.num_features = num_features
        self.eps = eps

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return rms_norm_module.rms_norm_forward_cuda(x, self.num_features, self.eps)
